code.cpp:
class Solution {
public:
    int maxConsecutiveAnswers(string answerKey, int k) {
        int n = answerKey.size();
        int ans = 0;
        for (char target : {'T', 'F'}) {
            int left = 0, cnt = 0;
            for (int right = 0; right < n; right++) {
                if (answerKey[right] != target) cnt++;
                while (cnt > k) {
                    if (answerKey[left] != target) cnt--;
                    left++;
                }
                ans = max(ans, right - left + 1);
            }
        }
        return ans;
    }
};
